script.source:
if (ctx.result !== "miss") return false;
const direction = await H.ask.one({
  title: "Misdirection",
  hint: "Shift 2 Threat into or out of your area.",
  options: [
    { value: "in", label: "Shift In" },
    { value: "out", label: "Shift Out" },
  ],
  applyLabel: "Shift",
});
if (!direction) return false;
return !!(await H.threat.shift(actor, {
  amount: 2,
  sourceConstraint: direction === "in" ? "adjacent" : "self",
  destConstraint: direction === "in" ? "self" : "adjacentToSource",
  excludeSupport: false,
  label: "Misdirection",
  reason: "Misdirection",
}));
